const schema = JSON.stringify({type:'object',properties:{group:{type:'string'},endpoints:{type:'array',items:{type:'string'}},scoping_evidence:{type:'array',items:{type:'string'}},tests_found:{type:'array',items:{type:'string'}},gaps_or_risks:{type:'array',items:{type:'string'}},suggested_regressions:{type:'array',items:{type:'string'}},summary:{type:'string'}},required:['group','endpoints','scoping_evidence','tests_found','gaps_or_risks','suggested_regressions','summary']});
const tasks=[
{group:'shop registration and documents',files:['ShopRegistrationController.java','ShopRegistrationService.java','ShopDocumentController.java','ShopDocumentRepository.java','ShopRegistrationDocumentAccessTest.java','ShopDocumentRepositoryTest.java'],brief:'Audit registration and document shop isolation',prompt:'Read-only source audit of SpindleTrack shop registration and verification-document endpoints for cross-shop isolation. Inspect only these files and their direct authorization/scoping helpers as needed: ShopRegistrationController.java, ShopRegistrationService.java, ShopDocumentController.java, ShopDocumentRepository.java, ShopRegistrationDocumentAccessTest.java, ShopDocumentRepositoryTest.java. Identify every route, how caller/shop ownership is derived, whether document ids can cross shops, and tests proving at least two-shop isolation. Do not edit files or run Git. Return exactly the shared JSON schema fields; cite file and line numbers in evidence. Be conservative and distinguish untested from vulnerable.'},
{group:'service catalog',files:['ShopServiceController.java','ShopServiceCatalog.java','ShopServiceCatalogTest.java','ShopServiceControllerTest.java'],brief:'Audit service catalog shop isolation',prompt:'Read-only source audit of SpindleTrack service-catalog endpoints for cross-shop isolation. Inspect only ShopServiceController.java, ShopServiceCatalog.java, ShopServiceCatalogTest.java, ShopServiceControllerTest.java and directly invoked auth/scoping helpers as needed. List routes and role gates; determine whether every read/write filters by caller shopId and whether string Firestore IDs are treated safely. Report current cross-shop tests using at least two shops and any gaps. Do not edit files or run Git. Return exactly the shared JSON schema fields, with file:line citations.'},
{group:'staff and invitations',files:['StaffManagementController.java','StaffManagementService.java','StaffManagementServiceTest.java'],brief:'Audit staff and invitation shop isolation',prompt:'Read-only audit of SpindleTrack staff and invitation endpoints for shop isolation. Inspect StaffManagementController.java, StaffManagementService.java, StaffManagementServiceTest.java plus direct authorization/scoping helpers as needed. Cover invite/list/resend/revoke/accept/decline, own-staff removal/list, and shop status/access checks. Explain whether IDs/tokens can operate across shops, whether staff identity is constrained to one shop, and whether tests use two shops. Do not edit files or run Git. Return exactly the shared JSON schema fields; cite file:line.'},
{group:'owner profile and presence',files:['OwnerShopController.java','OwnerShopService.java','OwnerStaffPresenceController.java','OwnerShopControllerTest.java','OwnerStaffPresenceControllerTest.java'],brief:'Audit owner profile and staff presence isolation',prompt:'Read-only audit of SpindleTrack owner shop-profile and owner staff-presence endpoints. Inspect OwnerShopController.java, OwnerShopService.java, OwnerStaffPresenceController.java, OwnerShopControllerTest.java, OwnerStaffPresenceControllerTest.java and direct helpers as needed. Determine how owner shopId is derived, whether profile edits/read and presence reads can cross shop boundaries, and whether tests explicitly compare two shops. Do not edit files or run Git. Return exactly the shared JSON schema fields with file:line citations.'},
{group:'orders and customer-linked reads',files:['ShopOrderController.java','ShopOrderService.java','CustomerOrderController.java','CustomerLinkedOrderService.java','ShopOrderServiceTest.java','CustomerOrderControllerTest.java','CustomerLinkedOrderServiceTest.java'],brief:'Audit order and customer-linked isolation',prompt:'Read-only audit of SpindleTrack order/payment and customer-linked order endpoints for cross-shop isolation. Inspect the declared ShopOrderController.java, ShopOrderService.java, CustomerOrderController.java, CustomerLinkedOrderService.java and named tests if present; direct auth helpers may be inspected. Cover staff/owner/admin/customer access, create/list/detail/advance/price/payment/cancel/online confirmation, and customer-linked list/detail. Report exact shopId enforcement and whether at least two shops are tested. Do not edit files or run Git. Return exactly the shared JSON schema fields with file:line citations. If any declared source filename is absent, mention it in gaps rather than guessing.'}
];
const results=await parallel('Audit five shop-owned endpoint groups',()=>tasks.map(t=>agent(t.prompt,{brief:t.brief,schema,input_files:t.files.map(f=>({path:'C:/Users/mikag/SpindleTrack/backend/src/'+(f.endsWith('Test.java')?'test/java/com/spindletrack/auth/':'main/java/com/spindletrack/auth/')+f,name:f})),sandbox:'shared',effort_level:'lite'})),{schema});
return results.map((r,i)=>r.ok?{item:tasks[i].group,result:r.value}:{item:tasks[i].group,error:r.error});

